sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.impact-section {
  width: 100%;
  padding: 90px 8%;
  background-color: #181818 !important;
  font-family: 'Poppins', 'Inter', sans-serif !important;
}

.impact-heading {
  max-width: 750px;
  margin: 0 auto 55px;
  text-align: center;
}

.impact-tag {
  color: #53BA00 !important;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 1.5px;
}

.impact-heading h2 {
  margin: 12px 0 15px;
  color: #FFFFFF !important;
  font-size: 36px;
  font-weight: 700;
}

.impact-heading p {
  margin: 0;
  color: #B0B0B0 !important;
  font-size: 16px;
  line-height: 1.6;
}

.impact-grid {
  max-width: 1150px;
  margin: auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.impact-card {
  padding: 30px 20px;
  background-color: #1F1F1F !important;
  border-radius: 12px;
  text-align: center;
  border: 1px solid rgba(255,255,255,0.08) !important;
}

.impact-number {
  color: #53BA00 !important;
  font-size: 38px;
  font-weight: bold;
  margin-bottom: 10px;
}

.impact-title {
  color: #FFFFFF !important;
  font-size: 16px;
  font-weight: bold;
  margin-bottom: 10px;
}

.impact-card p {
  margin: 0;
  color: #B0B0B0 !important;
  font-size: 13px;
  line-height: 1.6;
}

@media (max-width: 900px) {
  .impact-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .impact-grid {
    grid-template-columns: 1fr;
  }
  .impact-heading h2 {
    font-size: 30px;
  }
}
